CREATE FUNCTION public.guard_payment() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE total numeric; already numeric; BEGIN IF NOT public.is_admin() THEN RAISE EXCEPTION 'Administrator required'; END IF; PERFORM 1 FROM public.commission_agreements WHERE id=new.agreement_id FOR UPDATE; SELECT commission INTO total FROM public.transactions WHERE agreement_id=new.agreement_id; IF total IS NULL THEN RAISE EXCEPTION 'Confirmed transaction required'; END IF; SELECT coalesce(sum(amount),0) INTO already FROM public.commission_payments WHERE agreement_id=new.agreement_id AND id<>new.id; IF new.amount+already>total THEN RAISE EXCEPTION 'Payment exceeds outstanding commission'; END IF; RETURN new; END $$;
CREATE TRIGGER payment_guard BEFORE INSERT OR UPDATE ON public.commission_payments FOR EACH ROW EXECUTE FUNCTION public.guard_payment();
CREATE FUNCTION public.reconcile_payment() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a uuid; total numeric; paid numeric; BEGIN a:=CASE WHEN TG_OP='DELETE' THEN old.agreement_id ELSE new.agreement_id END; SELECT commission INTO total FROM public.transactions WHERE agreement_id=a; SELECT coalesce(sum(amount),0) INTO paid FROM public.commission_payments WHERE agreement_id=a; UPDATE public.commission_agreements SET status=CASE WHEN paid>=total THEN 'paid' ELSE 'due' END,updated_at=now() WHERE id=a AND total IS NOT NULL; RETURN NULL; END $$;
CREATE TRIGGER payment_reconcile AFTER INSERT OR UPDATE OR DELETE ON public.commission_payments FOR EACH ROW EXECUTE FUNCTION public.reconcile_payment();